module tb_TopModule;
    logic [15:0] scancode;
    logic left, down, right, up;

    TopModule dut (
        .scancode(scancode),
        .left(left),
        .down(down),
        .right(right),
        .up(up)
    );

    initial begin
        // Test left arrow
        scancode = 16'he06b;
        #10;
        if ({left, down, right, up} !== 4'b1000) begin
            $display("SELFTEST FAIL: left arrow failed, got %b", {left, down, right, up});
            $finish;
        end

        // Test down arrow
        scancode = 16'he072;
        #10;
        if ({left, down, right, up} !== 4'b0100) begin
            $display("SELFTEST FAIL: down arrow failed, got %b", {left, down, right, up});
            $finish;
        end

        // Test right arrow
        scancode = 16'he074;
        #10;
        if ({left, down, right, up} !== 4'b0010) begin
            $display("SELFTEST FAIL: right arrow failed, got %b", {left, down, right, up});
            $finish;
        end

        // Test up arrow
        scancode = 16'he075;
        #10;
        if ({left, down, right, up} !== 4'b0001) begin
            $display("SELFTEST FAIL: up arrow failed, got %b", {left, down, right, up});
            $finish;
        end

        // Test random scancode
        scancode = 16'h1234;
        #10;
        if ({left, down, right, up} !== 4'b0000) begin
            $display("SELFTEST FAIL: default failed, got %b", {left, down, right, up});
            $finish;
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule
